const rows = [];
const spec = [
  { category: 'Refund under 50 EUR', n: 420, overturned: 4, confidence: 0.71 },
  { category: 'Refund over 500 EUR', n: 38, overturned: 21, confidence: 0.74 },
  { category: 'Route ticket to a team', n: 1900, overturned: 22, confidence: 0.66 },
  { category: 'Reply to an angry customer', n: 260, overturned: 148, confidence: 0.81 },
  { category: 'Close duplicate ticket', n: 640, overturned: 9, confidence: 0.69 }
];
spec.forEach(function (s) {
  rows.push({ category: s.category, seen: s.n, overturned: s.overturned, avg_confidence: s.confidence });
});
return [{ json: { window: 'last 90 days', decisions: rows, threshold_today: 0.95 } }];

const d = $input.first().json;
const scored = d.decisions.map(function (c) {
  const regret = c.overturned / c.seen;
  let verdict = 'CALIBRATED';
  let action = 'Leave the gate where it is.';
  if (regret < 0.02) {
    verdict = 'THEATRE';
    action = 'The human changed nothing in ' + Math.round((1 - regret) * 100) + '% of cases. This gate is not review, it is a queue. Drop the threshold and let it through.';
  } else if (regret > 0.4) {
    verdict = 'SHOULD NOT BE AUTOMATED';
    action = 'The human rewrote ' + Math.round(regret * 100) + '% of these. The model is not doing this job. Stop asking it to.';
  }
  return {
    category: c.category, seen: c.seen, overturned: c.overturned,
    regret_rate: Number(regret.toFixed(3)), verdict: verdict, action: action,
    suggested_threshold: verdict === 'THEATRE' ? 0.6 : (verdict === 'SHOULD NOT BE AUTOMATED' ? 1.01 : 0.85),
    escalations_removed_per_week: verdict === 'THEATRE' ? Math.round((c.seen - c.overturned) / 13) : 0
  };
});
const theatre = scored.filter(function (s) { return s.verdict === 'THEATRE'; });
const stop = scored.filter(function (s) { return s.verdict === 'SHOULD NOT BE AUTOMATED'; });
const saved = scored.reduce(function (a, s) { return a + s.escalations_removed_per_week; }, 0);
const worst = scored.slice().sort(function (a, b) { return b.regret_rate - a.regret_rate; })[0];
const say = 'One global approval threshold of ' + d.threshold_today + ' is applied to five very different decisions. ' +
  theatre.length + ' of them are approval theatre - the human agreed with the model almost every time, so the gate only taught people to click Approve without reading. ' +
  stop.length + ' should never have been automated: \"' + (worst ? worst.category : 'n/a') + '\" was rewritten ' + (worst ? Math.round(worst.regret_rate * 100) : 0) + '% of the time. ' +
  'Setting the threshold per category instead of globally removes about ' + saved + ' pointless escalations a week and puts the attention where it changes an outcome.';
const headline = theatre.length > 0 ? 'theatre' : (stop.length > 0 ? 'stop' : 'calibrated');
return [{ json: { plain_english: say, headline: headline, per_category: scored, escalations_removed_per_week: saved } }];
